export const ITEM_BANK: SeedItem[] = [
  ...AI_ITEMS,
  ...BACKEND_ITEMS,
  ...FRONTEND_ITEMS,
  ...FULLSTACK_ITEMS,
  ...MOBILE_ITEMS,
  ...DEVOPS_ITEMS,
  ...DATA_ANALYST_ITEMS,
  ...QA_ITEMS,
  ...SS_ITEMS,
  ...ENG_ITEMS,
];

export async function seedItems(): Promise<void> {
  if (ITEM_BANK.length === 0) return;
  await db
    .insert(item)
    .values(
      ITEM_BANK.map((i) => ({
        id: i.id,
        stem: i.stem,
        choices: i.choices,
        dimension: i.dimension,
        difficultyB: i.difficultyB,
      })),
    )
    .onConflictDoUpdate({
      target: item.id,
      set: {
        stem: sql`excluded.stem`,
        choices: sql`excluded.choices`,
        dimension: sql`excluded.dimension`,
        difficultyB: sql`excluded.difficulty_b`,
      },
    });
}
